/**
 * Filling the demonstration.
 *
 * The restaurant it builds is generated by `shared/worked-example.js` — the
 * very same module the real server seeds a demonstration install with — so a
 * client clicking the published link and a restaurant seeing Saba on a laptop
 * are looking at one service, down to the paise.
 *
 * The staff and their PINs are the only thing invented here, and they are
 * printed on the lock screen on purpose: this is a showroom, not a till.
 */

import { buildWorkedExample } from '../../shared/worked-example.js';
import * as till from './store.js';

/** Who can sign in to the demonstration, and the PIN shown beside each. */
export const DEMO_STAFF = [
  { name: 'Manager', role: 'manager', pin: '1379' },
  { name: 'Alina Rahman', role: 'captain', pin: '2471' },
  { name: 'Devesh Kamat', role: 'cashier', pin: '3582' },
  { name: 'Kitchen Pass', role: 'kitchen', pin: '4693' },
];

const initials = (name) => name.trim().split(/\s+/).slice(0, 2)
  .map((w) => w[0] || '').join('').toUpperCase();

export function seedDemo() {
  till.reset();

  till.db.users = DEMO_STAFF.map((person) => ({
    id: `u_${person.role}`,
    name: person.name,
    initials: initials(person.name),
    role: person.role,
    pin: person.pin,
    active: true,
  }));

  const by = (role) => till.db.users.find((u) => u.role === role);
  const example = buildWorkedExample({
    today: till.today(),
    users: { manager: by('manager'), captain: by('captain'), cashier: by('cashier') },
    uid: () => `pay_${Math.random().toString(36).slice(2, 14)}`,
  });

  for (const order of example.orders) till.db.orders.set(order.id, order);
  for (const booking of example.reservations) till.db.reservations.set(booking.id, booking);
  for (const { itemId, by: who, note } of example.eightySix) {
    till.db.eightySix.set(itemId, { by: who, note, at: Date.now() });
  }
  // The generator allocated its own numbers; the till has to carry on from
  // them or the next bill would reuse one.
  till.db.counters = { ...example.counters };

  // The audit trail starts when the demonstration is opened: the month behind
  // it was generated, not transacted, and claiming otherwise would be a lie
  // on the one screen whose whole job is to be trustworthy.
  till.db.audit = [];
  till.audit('SYSTEM', 'Demonstration opened — a month of trading and a room in service',
    { actor: 'Saba' });
  till.bump();

  return example;
}
